from __future__ import absolute_import
from hran_radio.radio_connection.telnet_interface import TelnetConnection
from hran_radio.radio_output_parser.alu_parser import TxAluParser, CarrierConfigAluParser
from hran_radio.exceptions import NotSupportedFunctionForRmod
from .radio_base import RadioBase


class RadioALU(RadioBase):
    def __init__(self, radio_ip, system_module_ip, master_system_module_ip):
        super(RadioALU, self).__init__(
            radio_ip, system_module_ip, master_system_module_ip
        )
        self.message_get_type = "MESSAGE: TYPE=GET\nTRANSACTION: ID=50"
        self.carrier_config_command = "[\n{}\nCARRIERCFG: INDEX=1\nCARRIERCFG: INDEX=2\nCARRIERCFG: INDEX=3\n]".format(
            self.message_get_type
        )
        self.raw_carriercfg = None
        self.radio_connection = TelnetConnection(
            self._radio_ip, self._sm_ip, self._msm_ip, "1307"
        )
        self.release = self.radio_connection.get_smod_release()

    def all_tx_power(self):
        """
        Return all tx power in format {tx: power}.

        :return: tx power
        :rtype: dict
        """
        raw_output = self.run_radio_command(self.get_tx_power_command())
        tx_parser = TxAluParser(raw_output)
        return tx_parser.parse_tx_power()

    def all_rx_power(self):
        """NOT IMPLEMENTED YET"""

    def lte_tx_power(self):
        """
        Return tx power for LTE technology.

        :return: tx power
        :rtype: dict
        """
        return self._get_tx_power_for("LTE")

    def wcdma_tx_power(self):
        """
        Return tx power for WCDMA technology.

        :return: tx power
        :rtype: dict
        """
        return self._get_tx_power_for("WCDMA")

    def gsm_tx_power(self):
        """
        Return tx power for GSM technology.

        :return: tx power
        :rtype: dict
        """
        return self._get_tx_power_for("GSM")

    def front_end_gain(self, antenna_number):
        """
        This method is specific for Nokia rmod
        """
        raise NotSupportedFunctionForRmod()

    def tx_carrier_data(self):
        """
        This method is specific for Nokia rmod
        """
        raise NotSupportedFunctionForRmod()

    def rx_carrier_data(self):
        """
        This method is specific for Nokia rmod
        """
        raise NotSupportedFunctionForRmod()

    def get_tx_power_command(self):
        """
        Check ALU carrier config and return command to
        get all txs power.

        :return: Alu tx power command for all tx.
        :rtype: str
        """
        command = "[\n{}\n".format(self.message_get_type)
        carrier_cfg = self._prepare_tx_data()
        for index, tx_paths in carrier_cfg.parse_tx_path().items():
            command += self._set_tx_path_in_command(index, tx_paths)
        return command + "]"

    def _prepare_tx_data(self):
        self.raw_carriercfg = self.run_radio_command(self.carrier_config_command)
        carrier_cfg = CarrierConfigAluParser(self.raw_carriercfg)
        return carrier_cfg

    @staticmethod
    def _set_tx_path_in_command(index, tx_paths):
        tx_command = ""
        for path in tx_paths:
            if path == "1":
                tx_command += "TXPOWER: INDEX={}\n".format(index)
            else:
                tx_command += "TX{}POWER: INDEX={}\n".format(path, index)
        return tx_command

    def _get_tx_power_for(self, technology):
        tx_power_dict = self.all_tx_power()
        carrier_cfg = CarrierConfigAluParser(self.raw_carriercfg)
        tx_tech = carrier_cfg.parse_technology()
        return {
            tx_num: power
            for tx_num, power in tx_power_dict.items()
            if tx_tech[tx_num[0]] == technology
        }
